import api from "./api";
import { FEATURES } from "../constants/AppConstants";

const MOCK_KEY = "campusmobi_mock_wallet";

function readMockWallet() {
  const raw = localStorage.getItem(MOCK_KEY);
  if (raw) {
    try {
      return JSON.parse(raw);
    } catch {
      // fall through to default
    }
  }
  const initial = {
    balance: 245.5,
    currency: "ZAR",
    transactions: [
      { id: "t1", label: "Cafeteria — lunch", amount: -45.0, date: "2026-08-08" },
      { id: "t2", label: "Wallet top-up", amount: 200.0, date: "2026-08-05" },
      { id: "t3", label: "Printing — 12 pages", amount: -9.6, date: "2026-08-03" },
    ],
  };
  localStorage.setItem(MOCK_KEY, JSON.stringify(initial));
  return initial;
}

function writeMockWallet(wallet) {
  localStorage.setItem(MOCK_KEY, JSON.stringify(wallet));
  return wallet;
}

const WalletService = {
  async getWallet() {
    try {
      const { data } = await api.get("/wallet");
      return data;
    } catch (err) {
      if (!FEATURES.ENABLE_MOCK_FALLBACK) throw err;
      return readMockWallet();
    }
  },

  async addFunds(amount) {
    try {
      const { data } = await api.post("/wallet/topup", { amount });
      return data;
    } catch (err) {
      if (!FEATURES.ENABLE_MOCK_FALLBACK) throw err;
      const wallet = readMockWallet();
      wallet.balance = Number((wallet.balance + amount).toFixed(2));
      wallet.transactions.unshift({
        id: "t" + Date.now(),
        label: "Wallet top-up (simulated)",
        amount: Number(amount.toFixed(2)),
        date: new Date().toISOString().slice(0, 10),
      });
      return writeMockWallet(wallet);
    }
  },

  async pay(amount, label) {
    try {
      const { data } = await api.post("/wallet/pay", { amount, label });
      return data;
    } catch (err) {
      if (!FEATURES.ENABLE_MOCK_FALLBACK) throw err;
      const wallet = readMockWallet();
      wallet.balance = Number((wallet.balance - amount).toFixed(2));
      wallet.transactions.unshift({
        id: "t" + Date.now(),
        label: label || "Simulated payment",
        amount: -Number(amount.toFixed(2)),
        date: new Date().toISOString().slice(0, 10),
      });
      return writeMockWallet(wallet);
    }
  },
};

export default WalletService;
